import os
import requests

def redact_unsafe(payload, config=None):
    config = config or {}
    api_key = config.get('api_key') or os.environ.get('HIVE_MODERATION_API_KEY')
    if api_key:
        url = 'https://moderation.hive.com/v1/task/sync'
        headers = {
            'x-api-key': api_key,
            'content-type': 'application/json'
        }
        body = {
            'data': {
                'text': payload
            }
        }
        resp = requests.post(url, headers=headers, json=body)
        if resp.status_code == 200:
            try:
                data = resp.json()
                explanations = data['results'][0]['result']['explanation']
                text = payload
                spans = sorted(explanations, key=lambda x: x.get('start_index', 0), reverse=True)
                for span in spans:
                    start = span['start_index']
                    end = span['end_index']
                    text = text[:start] + '[REDACTED]' + text[end:]
                redacted_text = text
            except:
                redacted_text = payload
        else:
            redacted_text = payload
    else:
        redacted_text = payload
    result = redacted_text
    return result
